 goal='eu consigo recuperar, em contextos novos, o que estudei na Unidade 5 do C2: concessões sofisticadas, registro, do, e gêneros do discurso público (elogio, réplica, notícia, carta, aviso, moderação).',
 read=('Reading · A short report',text('Report: Speaking Up, Fairly',['Whether one **writes to a representative**, **rebuts** an opponent or **moderates** a debate, fairness depends on form. **Much as** we admire fiery speech, **however passionate** the speaker, a reply that **concedes** a small point **earns** credibility. **Albeit** brief, a polite formula such as “**I must stop you there**” keeps order.','Careful speakers also **adapt register**: what **reads well** at a podium may **sound stiff** online. And when a committee **does away with** a procedure, citizens should ask who **will do without** a voice. **Be that as it may**, public life **runs on** patience.'],kicker='REPORT',by='Civic Language Lab',gloss=[('fiery','inflamado'),('concede','conceder'),('stiff','rígido'),('run on','funcionar à base de')])),
 tf=[('A reply that concedes a small point loses credibility.','F','earns credibility.'),('A polite formula can keep order.','T','I must stop you there.'),('Online text should copy podium style exactly.','F','may sound stiff online.')],
 mc=[('“do away with” = ?',['abolir','fazer longe','vencer'],0,'do away with.'),('“albeit” = ?',['embora, ainda que','além disso','portanto'],0,'albeit.')],
 recap=[table(['Verifique','Exemplo'],[['**Concessões**: albeit, much as, however + adj','**Albeit** brief; **Much as** we admire…'],['**Do**: do away with, do without, do justice to','They **did away with** the fee'],['**Registro**: formal ↔ informal','**It is incumbent upon us** → **We’ve got to**'],['**Gêneros**: elogio, réplica, notícia, carta, aviso','steps, rebuttal, report'],['**Moderar e interpretar**','cut off politely; compress, never distort']],'Lista de verificação da Unidade 5 (C2)')],
 dlg=('Unit review',[('Ana','Was the speech effective?','O discurso foi eficaz?'),('Leo','Much as I admire her, I found it too long.','Por mais que a admire, achei longo demais.'),('Ana','Did she concede anything?','Ela concedeu algo?'),('Leo','Albeit briefly, yes, and that helped.','Ainda que brevemente, sim, e isso ajudou.')]),
 speak_=[('Make a concession with much as.','Conceda.','Much as I like the plan, I cannot support it.'),('Use do away with.','Use.','They did away with the old procedure.'),('Transpose a formal phrase into a casual one.','Transponha.','Commence becomes start.')],
 wr=('Write a 6-sentence paragraph on fairness in public debate, using the unit structures.','Much as we value passion, a fair debate needs rules. However heated the topic, a moderator must stay neutral. Albeit brief, a concession can earn the audience’s trust. Some councils have done away with public comment, which seems unwise. We cannot do without citizens’ voices. Be that as it may, patience remains the best rule.',['Usei **much as / however**','Usei **albeit**','Usei **do away with / do without**'],'6 frases'),
